description:
Like Vulkan, pack a version into one number: `major << 22 | minor << 12 | patch`, with 10 bits for minor and 12 for patch. Write

```cpp
uint32_t packVersion(uint32_t major, uint32_t minor, uint32_t patch);
void unpackVersion(uint32_t packed, uint32_t& major, uint32_t& minor, uint32_t& patch);
```

Values that do not fit are cut to their field width: `minor & 0x3FF`, `patch & 0xFFF`.

starter.solution.cpp:
#include <cstdint>

uint32_t packVersion(uint32_t major, uint32_t minor, uint32_t patch) { return 0; }
void unpackVersion(uint32_t packed, uint32_t& major, uint32_t& minor, uint32_t& patch) {}

solution.solution.cpp:
#include <cstdint>

uint32_t packVersion(uint32_t major, uint32_t minor, uint32_t patch)
{
    return (major << 22) | ((minor & 0x3FFu) << 12) | (patch & 0xFFFu);
}

void unpackVersion(uint32_t packed, uint32_t& major, uint32_t& minor, uint32_t& patch)
{
    major = packed >> 22;
    minor = (packed >> 12) & 0x3FFu;
    patch = packed & 0xFFFu;
}

unitTests:
TEST("pack") { CHECK_EQ(packVersion(2, 4, 1), (2u << 22) | (4u << 12) | 1u); CHECK_EQ(packVersion(0, 0, 0), 0u); }
TEST("round trip") { uint32_t a = 0, b = 0, c = 0; unpackVersion(packVersion(1, 3, 250), a, b, c); CHECK_EQ(a, 1u); CHECK_EQ(b, 3u); CHECK_EQ(c, 250u); }
TEST("newer is bigger") { CHECK(packVersion(2, 10, 0) > packVersion(2, 9, 999)); CHECK(packVersion(3, 0, 0) > packVersion(2, 1023, 4095)); }
TEST("cut to width") { uint32_t a = 0, b = 0, c = 0; unpackVersion(packVersion(1, 1024 + 5, 4096 + 7), a, b, c); CHECK_EQ(b, 5u); CHECK_EQ(c, 7u); }

